const searchListings = `-- name: SearchListings :many
SELECT e.id, e.title, e.instant_book, e.rating_avg, e.rating_count, e.wet_hire, e.dry_hire,
       c.slug AS category_slug, m.name AS model_name, mk.name::text AS make_name,
       o.display_name AS owner_name, (o.kyc_status = 'verified')::bool AS owner_verified,
       p.rate_paise, p.unit, p.with_operator,
       -- Approximate (public point): exact positions are never revealed.
       (ST_Distance(e.public_location, site.g) / 1000.0)::float8 AS distance_km,
       COALESCE((SELECT md.object_key FROM equipment_media md
         WHERE md.equipment_id = e.id AND md.deleted_at IS NULL
         ORDER BY md.is_cover DESC, md.sort_order LIMIT 1), '')::text AS cover_object_key
FROM equipment e
JOIN equipment_models m ON m.id = e.model_id
JOIN equipment_makes mk ON mk.id = m.make_id
JOIN equipment_categories c ON c.id = m.category_id
JOIN organizations o ON o.id = e.owner_org_id
JOIN pricing_plans p ON p.equipment_id = e.id AND p.is_active AND p.unit = $1 AND p.with_operator = $2
CROSS JOIN (SELECT ST_SetSRID(ST_MakePoint($3::float8, $4::float8), 4326)::geography AS g) site
WHERE e.status = 'active'
  AND e.deleted_at IS NULL
  AND ($5::text IS NULL OR c.slug = $5)
  AND ($6::uuid IS NULL OR mk.id = $6)
  AND ($7::bigint IS NULL OR p.rate_paise <= $7)
  AND (NOT $8::bool OR o.kyc_status = 'verified')
  AND ($9::text IS NULL OR e.title ILIKE '%' || $9 || '%' OR m.name ILIKE '%' || $9 || '%')
  AND ST_DWithin(e.base_location, site.g, LEAST(e.service_radius_km, $10::int) * 1000.0)
  AND NOT EXISTS (
    SELECT 1 FROM bookings b
    WHERE b.equipment_id = e.id AND booking_holds_slot(b.status, b.resume_status)
      AND b.period && tstzrange($11::timestamptz, $12::timestamptz, '[)'))
  AND NOT EXISTS (
    SELECT 1 FROM availability_blocks a
    WHERE a.equipment_id = e.id AND a.period && tstzrange($11::timestamptz, $12::timestamptz, '[)'))
ORDER BY
  CASE WHEN $13::text = 'price' THEN p.rate_paise END ASC,
  CASE WHEN $13::text = 'rating' THEN e.rating_avg END DESC NULLS LAST,
  distance_km ASC, e.id
LIMIT $15 OFFSET $14
`

