const upsertMobilisationRate = `-- name: UpsertMobilisationRate :exec
INSERT INTO mobilisation_rates (equipment_id, fixed_paise, per_km_paise, free_km, needs_trailer)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (equipment_id) DO UPDATE
SET fixed_paise = EXCLUDED.fixed_paise, per_km_paise = EXCLUDED.per_km_paise,
    free_km = EXCLUDED.free_km, needs_trailer = EXCLUDED.needs_trailer
`

type UpsertMobilisationRateParams struct {
	EquipmentID  uuid.UUID `json:"equipment_id"`
	FixedPaise   int64     `json:"fixed_paise"`
	PerKmPaise   int64     `json:"per_km_paise"`
	FreeKm       int32     `json:"free_km"`
	NeedsTrailer bool      `json:"needs_trailer"`
}

func (q *Queries) UpsertMobilisationRate(ctx context.Context, arg UpsertMobilisationRateParams) error {
	_, err := q.db.Exec(ctx, upsertMobilisationRate,
		arg.EquipmentID,
		arg.FixedPaise,
		arg.PerKmPaise,
		arg.FreeKm,
		arg.NeedsTrailer,
	)
	return err
}
